function getTableauPulseTranslation(key, lang) {
    return (tableaupulseTranslations[lang] && tableaupulseTranslations[lang][key]) ||
           (tableaupulseTranslations.en && tableaupulseTranslations.en[key]) || null;
}

function applyTableauPulseTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.tableau-pulse.") || key.startsWith("review.common."))) {
            const translation = getTableauPulseTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    
}

window.addEventListener("languageChanged", e => setTimeout(() => applyTableauPulseTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyTableauPulseTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyTableauPulseTranslations(window.i18n?.getCurrentLanguage() || "en");
}
